<?php
require 'includes/bootstrap.php';require_admin();require 'includes/layout.php';require 'includes/account_controls.php';require 'includes/partner_registration_admin.php';require_once 'includes/deletions.php';require_once 'includes/people_directory.php';
$view=($_GET['view']??'customers')==='collaborators'?'collaborators':'customers';$uid=trim((string)($_GET['id']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$uid=(string)($_POST['user_id']??'');
 try{if(($_POST['action']??'')==='delete'){if(($_POST['confirmation']??'')!=='1')throw new RuntimeException('Confirma la eliminación antes de continuar.');delete_managed('users',$uid,(string)($_POST['revision']??''),trim((string)($_POST['reason']??'')));flash('success','Cuenta eliminada con copia recuperable.');redirect('users.php?view='.$view);}elseif(($_POST['action']??'')==='registration'){partner_registration_admin_action($uid,$_POST);flash('success','Revisión guardada.');redirect('users.php?view=collaborators'.(($_POST['registration_action']??'')==='settings'?'&registration=settings':'&id='.rawurlencode($uid)));}apply_account_decision($uid,(string)($_POST['action']??''),(string)($_POST['status']??''),trim((string)($_POST['reason']??'')),(string)($_POST['revision']??''));flash('success','Decisión guardada.');}
 catch(Throwable $e){flash('error',$e instanceof PDOException?'No se pudo guardar. Inténtalo de nuevo.':$e->getMessage());}
 redirect('users.php?view='.$view.((($_POST['action']??'')==='delete')?'':'&id='.rawurlencode($uid)));
}
if(($_GET['registration']??'')==='settings')render_partner_registration_settings();
if(isset($_GET['private_document'])){
 require_owner();$upload=(string)$_GET['private_document'];
 $s=db()->prepare('SELECT path,content_type,purpose FROM uploads WHERE id=? AND user_id=?');$s->execute([$upload,$uid]);$doc=$s->fetch();$file=$doc?(str_starts_with($doc['path'],'private-documents/')?partner_private_file($doc['path']):(in_array($doc['purpose'],['vehicle-photo','professional-photo','professional-cover','professional-gallery'],true)?stored_asset_file($doc['path']):null)):null;
 if(!$file){http_response_code(404);exit;}
 db()->prepare("INSERT INTO audit_log(admin_id,action,entity_type,entity_id,details_json) VALUES(?,'private_document.viewed','upload',?,'{}')")->execute([admin()['id'],$upload]);
 header('Content-Type: '.$doc['content_type']);header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'none'; sandbox");readfile($file);exit;
}
function person_table(array $headers,array $rows):void{echo '<div class="table-wrap"><table><thead><tr>';foreach($headers as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($row as $cell)echo '<td>'.$cell.'</td>';echo '</tr>';}if(!$rows)echo '<tr><td colspan="'.count($headers).'">Sin registros.</td></tr>';echo '</tbody></table></div>';}
if(isset($_GET['photo'])){
 $s=db()->prepare("SELECT p.profile_json FROM partner_profiles p WHERE p.user_id=?");$s->execute([$uid]);$data=json_decode($s->fetchColumn()?:'{}',true);$id=$data['professionalPhotoUploadId']??'';
 $s=db()->prepare("SELECT path,content_type,purpose FROM uploads WHERE id=? AND user_id=? AND purpose='professional-photo'");$s->execute([$id,$uid]);$photo=$s->fetch();$file=$photo?stored_asset_file($photo['path']):null;
 if(!$file){http_response_code(404);exit;}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true)){http_response_code(415);exit;}
 header('Content-Type: '.$mime);header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');readfile($file);exit;
}
