echo '<nav class="filters people-tabs" aria-label="Directorio"><a href="users.php?view=customers" '.($view==='customers'?'aria-current="page"':'').'>Clientes</a><a href="users.php?view=collaborators" '.($view==='collaborators'?'aria-current="page"':'').'>Colaboradores</a></nav>';
if($uid===''){render_people_directory($view);page_footer();exit;}
$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$uid]);$user=$s->fetch();
if(!$user){http_response_code(404);echo '<section class="panel">Esta cuenta no existe.</section>';page_footer();exit;}
$s=db()->prepare('SELECT * FROM partner_profiles WHERE user_id=?');$s->execute([$uid]);$partner=$s->fetch()?:null;
$professional=$user['role']==='partner'||$user['partner_intent'];$control=account_control($uid);$revision=account_revision($user,$partner,$control);
$profile=json_decode($user['profile_json'],true,512,JSON_THROW_ON_ERROR);$business=$partner?json_decode($partner['profile_json'],true,512,JSON_THROW_ON_ERROR):[];
if(empty($business['citiesText'])&&is_array($business['cities']??null))$business['citiesText']=implode(', ',array_filter($business['cities'],'is_string'));
$owner=$view==='collaborators'?'partner_user_id':'customer_user_id';
$s=db()->prepare("SELECT status,COUNT(*) total FROM reservations WHERE `$owner`=? GROUP BY status");$s->execute([$uid]);$totals=array_fill_keys(array_keys(reservation_labels()),0);foreach($s->fetchAll() as $row)$totals[$row['status']]=(int)$row['total'];
$historyPage=max(1,(int)($_GET['history_page']??1));$historyOffset=($historyPage-1)*25;
$s=db()->prepare("SELECT r.*,q.total_minor,q.currency,CONCAT(c.first_name,' ',c.last_name) customer_name,CONCAT(p.first_name,' ',p.last_name) partner_name FROM reservations r JOIN quotes q ON q.id=r.quote_id JOIN users c ON c.id=r.customer_user_id LEFT JOIN users p ON p.id=r.partner_user_id WHERE r.`$owner`=? ORDER BY r.created_at DESC,r.id DESC LIMIT 25 OFFSET $historyOffset");$s->execute([$uid]);$history=$s->fetchAll();
$walletType=$view==='collaborators'?'partner':'customer';$s=db()->prepare('SELECT currency,status,SUM(amount_minor) amount FROM wallet_ledger WHERE user_id=? AND wallet_type=? GROUP BY currency,status');$s->execute([$uid,$walletType]);$wallet=[];foreach($s->fetchAll() as $row)$wallet[$row['currency']][$row['status']]=(int)$row['amount'];
$s=db()->prepare('SELECT entry_type,amount_minor,currency,status,description,created_at FROM wallet_ledger WHERE user_id=? AND wallet_type=? ORDER BY created_at DESC,id DESC LIMIT 50');$s->execute([$uid,$walletType]);$moves=$s->fetchAll();
$s=db()->prepare("SELECT a.action,a.details_json,a.created_at,ad.name administrator FROM audit_log a LEFT JOIN admins ad ON ad.id=a.admin_id WHERE (a.entity_type IN ('user','partner_profile') AND a.entity_id=?) OR (a.entity_type='reservation' AND EXISTS(SELECT 1 FROM reservations r WHERE r.id=a.entity_id AND r.`$owner`=?)) ORDER BY a.id DESC LIMIT 50");$s->execute([$uid,$uid]);$events=$s->fetchAll();
?>
