<div id="person-professional"></div><?php if($professional)render_partner_registration($uid,$partner,$business);?><section class="panel" id="person-services"><h3>Historial de servicios</h3><?php $canDelete=can_manage_deletions('delete');$cells=[];foreach($history as $r)$cells[]=[e($r['created_at']).'<small>'.e($r['service_type']==='driver'?'Chófer':'Guía').' · '.e($r['id']).'</small>',e($r['customer_name']).'<small>'.e($r['partner_name']?:'Sin asignar').'</small>',e(reservation_labels()[$r['status']]??$r['status']),e(admin_money((int)$r['total_minor'],$r['currency'])).'<small>'.e(['notCollected'=>'Sin cobrar','pending'=>'Pago pendiente','paid'=>'Pagado','refunded'=>'Reembolsado'][$r['payment_status']]??$r['payment_status']).'</small>','<a href="reservations.php?id='.e(rawurlencode($r['id'])).'">Ver servicio</a>'];person_table(['Fecha / servicio','Cliente / colaborador','Estado','Importe / pago','Gestión'],$cells);?><nav class="directory-pagination"><?php if($historyPage>1):?><a href="?<?=e(http_build_query(['view'=>$view,'id'=>$uid,'history_page'=>$historyPage-1]))?>">← Anteriores</a><?php endif;?><?php if($historyOffset+25<array_sum($totals)):?><a href="?<?=e(http_build_query(['view'=>$view,'id'=>$uid,'history_page'=>$historyPage+1]))?>">Más servicios →</a><?php endif;?></nav></section>
<section class="panel" id="person-wallet"><h3>Billetera · saldo contable</h3><p>Importes registrados por moneda. La comisión se conserva en cada reserva; no se crean ganancias ni pagos al cambiar un estado.</p><div class="wallet-totals"><?php foreach($wallet as $currency=>$amounts):?><article><strong><?=e($currency)?></strong><?php foreach(['pending'=>'Pendiente','available'=>'Disponible','paid'=>'Liquidado','void'=>'Anulado'] as $status=>$label):?><p><?=e($label)?> <strong><?=e(admin_money($amounts[$status]??0,$currency))?></strong></p><?php endforeach;?></article><?php endforeach;?><?php if(!$wallet):?><p>Sin saldo ni movimientos contabilizados.</p><?php endif;?></div><details><summary>Últimos 50 movimientos</summary><?php $canDelete=can_manage_deletions('delete');$cells=[];foreach($moves as $move)$cells[]=[e($move['created_at']),e($move['description']?:$move['entry_type']),e(admin_money((int)$move['amount_minor'],$move['currency'])),e(['pending'=>'Pendiente','available'=>'Disponible','paid'=>'Liquidado','void'=>'Anulado'][$move['status']]??$move['status'])];person_table(['Fecha','Concepto','Importe','Estado'],$cells);?></details></section>
<?php if($professional):$s=db()->prepare("SELECT 'driver' type,id,status,city,title_json FROM driver_services WHERE owner_user_id=? UNION ALL SELECT 'guide',id,status,city,title_json FROM guide_services WHERE owner_user_id=? ORDER BY status,id");$s->execute([$uid,$uid]);$services=$s->fetchAll();$s=db()->prepare("SELECT r.rating,r.comment,r.author_name,r.created_at FROM reviews r WHERE (r.service_type='driver' AND EXISTS(SELECT 1 FROM driver_services s WHERE s.id=r.service_id AND s.owner_user_id=?)) OR (r.service_type='guide' AND EXISTS(SELECT 1 FROM guide_services s WHERE s.id=r.service_id AND s.owner_user_id=?)) ORDER BY r.created_at DESC,r.id DESC LIMIT 50");$s->execute([$uid,$uid]);$reviews=$s->fetchAll();?>
